function squeezeRepeats(nums: number[]): void {
  let end = nums.length; // nums[0 .. end) is still being cleaned
  let i = 1;
  while (i < end) {
    if (nums[i] === nums[i - 1]) {
      for (let j = i; j < end - 1; j++) nums[j] = nums[j + 1];
      end--;
    } else {
      i++;
    }
  }
}

