class Solution:
    def squeezeRepeats(self, nums: List[int]) -> None:
        end, i = len(nums), 1  # nums[0:end] is still being cleaned
        while i < end:
            if nums[i] == nums[i - 1]:
                for j in range(i, end - 1):
                    nums[j] = nums[j + 1]
                end -= 1
            else:
                i += 1

